import json, sys
data = json.load(sys.stdin)
result = json.loads(data['result'])
exps = result['data']['experiments']
# Find related OpenVLA Long experiments and TraceVLA untrained experiments for comparison
related = {}
for k,v in exps.items():
    if ('openvla_long' in k or ('untrained' in k and v.get('status') == 'DONE')) and k != 'openvla_long_untrained_v1':
        related[k] = {
            'status': v.get('status'),
            'conclusion': v.get('conclusion'),
            'metrics': v.get('metrics'),
            'hypothesis': v.get('hypothesis', '')[:120]
        }
for k,v in sorted(related.items()):
    print(f'--- {k} ---')
    print(json.dumps(v, indent=2, ensure_ascii=False))
    print()
